import json

convs = []
with open('data/generated/dd_test5.jsonl') as f:
    for line in f:
        convs.append(json.loads(line))

for c in convs[:3]:
    print(f\"=== {c['conversation_id']} ({c['num_turns']} turns) ===\")
    print(f\"Goal: {c['harmful_goal'][:70]}\")
    print(f\"Framing: {c['positive_topic']}\")
    for i, t in enumerate(c['turns']):
        if t['role'] == 'user':
            s = t.get('intended_strategy', '?')
            sname = {0:'rapport',1:'authority',2:'emotion',3:'reframe',4:'role',5:'escalate',6:'obfuscate',7:'direct'}.get(s, str(s))
            print(f'  T{i//2+1} [{sname}]: {t[\"content\"][:180]}')
    has_think = any('<think>' in t['content'] for t in c['turns'])
    if has_think:
        print('  *** <think> LEAK ***')
    print()

# check duplicates
print('=== Duplicate Check ===')
for c in convs:
    user_turns = [t['content'] for t in c['turns'] if t['role'] == 'user']
    for i in range(len(user_turns)):
        for j in range(i+1, len(user_turns)):
            words_i = set(user_turns[i].lower().split())
            words_j = set(user_turns[j].lower().split())
            if words_i and words_j:
                overlap = len(words_i & words_j) / max(len(words_i), len(words_j))
                if overlap > 0.7:
                    print(f'  {c[\"conversation_id\"]}: T{i+1} and T{j+1} overlap={overlap:.2f}')
print('Done')
